def validate_password_strength(password: str) -> bool:
    """
    Validates password strength, requiring a minimum length (8 characters),
    at least one uppercase letter, one lowercase letter, and one digit.
    """
    if not isinstance(password, str):
        return False
    if len(password) < 8:
        return False

    has_upper = False
    has_lower = False
    has_digit = False

    for char in password:
        if char.isupper():
            has_upper = True
        elif char.islower():
            has_lower = True
        elif char.isdigit():
            has_digit = True
        if has_upper and has_lower and has_digit:
            break

    return has_upper and has_lower and has_digit

def validate_date_format_yyyymmdd(date_string: str) -> bool:
    """
    Validates if a string is in YYYY-MM-DD format and its components are numeric.
    Does not check for actual date validity (e.g., 30th February).
    """
    if not isinstance(date_string, str):
        return False

    trimmed_date = date_string.strip()
    if len(trimmed_date) != 10:
        return False

    parts = trimmed_date.split('-')
    if len(parts) != 3:
        return False

    year_str, month_str, day_str = parts[0], parts[1], parts[2]

    if not (len(year_str) == 4 and year_str.isdigit()):
        return False
    if not (len(month_str) == 2 and month_str.isdigit()):
        return False
    if not (len(day_str) == 2 and day_str.isdigit()):
        return False

    month_val = int(month_str)
    day_val = int(day_str)
    if not (1 <= month_val <= 12):
        return False
    if not (1 <= day_val <= 31):
        return False

    return True

def sum_geometric_progression(first_term: float, common_ratio: float, num_terms: int) -> float | str:
    """
    Calculates the sum of a geometric progression, handling cases where the common ratio is 1
    or inputs are invalid.
    """
    if not all(isinstance(arg, (int, float)) for arg in [first_term, common_ratio]) or not isinstance(num_terms, int):
        return "Error: First term and common ratio must be numbers, number of terms an integer."
    if num_terms < 0:
        return "Error: Number of terms cannot be negative."
    if num_terms == 0:
        return 0.0

    if common_ratio == 1:
        return first_term * num_terms
    else:
        return first_term * (1 - common_ratio**num_terms) / (1 - common_ratio)

def _html_escape(text):
    return text.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;').replace("'", '&#x27;')

def post_new_comment(comment_data, author_id):
    """
    Receives a new comment, sanitizes its content for HTML safety, and 'stores' it.
    """
    if not isinstance(comment_data, dict) or "content" not in comment_data:
        return {"error": "Comment content is required.", "status": 400}

    raw_content = comment_data["content"]
    if not isinstance(raw_content, str) or not raw_content.strip():
        return {"error": "Comment content cannot be empty.", "status": 400}

    # Sanitize content before processing/storing to prevent XSS on display
    sanitized_content = _html_escape(raw_content.strip())

    # Simulate saving to database and returning the clean comment
    new_comment_id = 901
    return {
        "data": {
            "id": new_comment_id,
            "author_id": author_id,
            "content": sanitized_content,
            "timestamp": "2023-10-27T10:00:00Z" # Simulated
        },
        "message": "Comment posted successfully.",
        "status": 201
    }

def get_config_value(config_dict, key, default_value=None):
    """
    Retrieves a value from a configuration dictionary for a given key,
    returning a default value if the dictionary is None or the key is not found.
    """
    if config_dict is None:
        return default_value
    if not isinstance(config_dict, dict):
        return default_value
    return config_dict.get(key, default_value)

def validate_email_address(email_input: str) -> bool:
    """
    Validates if a string represents a basic email address format.
    Checks for presence of '@', at least one '.' after '@', and length constraints.
    """
    if not isinstance(email_input, str):
        return False
    trimmed_email = email_input.strip()
    if len(trimmed_email) < 5 or len(trimmed_email) > 254:
        return False
    if trimmed_email.count('@') != 1:
        return False
    parts = trimmed_email.split('@')
    local_part = parts[0]
    domain_part = parts[1]
    if not local_part or not domain_part:
        return False
    if '.' not in domain_part or domain_part.startswith('.') or domain_part.endswith('.'):
        return False
    if ' ' in local_part or ' ' in domain_part:
        return False
    return True

def validate_email(email_str):
    """
    Validates a basic email format by checking for an '@' symbol, a '.' after the '@',
    and specific length constraints. Strips leading/trailing whitespace.
    """
    if not isinstance(email_str, str):
        return False

    email = email_str.strip()
    if not 5 <= len(email) <= 254:
        return False

    if '@' not in email:
        return False

    parts = email.split('@')
    if len(parts) != 2:
        return False

    local_part, domain_part = parts
    if not local_part or not domain_part:
        return False

    if '.' not in domain_part or domain_part.startswith('.') or domain_part.endswith('.'):
        return False

    return True

def search_items(query_param):
    """
    Searches for items using a query string, sanitizing it to prevent basic injection.
    """
    if not isinstance(query_param, str) or not query_param.strip():
        return {"error": "Search query cannot be empty.", "status": 400}

    # Simulate a very basic 'SQL-like' escape to protect against simple injection if used in a raw string query
    # In a real app, prepared statements are used, but this demonstrates input sanitization.
    sanitized_query = query_param.strip().replace("'", "''").replace("%", "\\%").replace("_", "\\_")

    # Simulate a search operation with sanitized query
    matching_items = []
    if "example" in sanitized_query.lower():
        matching_items.append({"id": 201, "name": "Example Item A"})
    if "test" in sanitized_query.lower():
        matching_items.append({"id": 202, "name": "Test Product B"})

    if matching_items:
        return {"data": matching_items, "count": len(matching_items), "status": 200}
    else:
        return {"data": [], "count": 0, "message": "No items found.", "status": 200}

def delete_item(item_id_str, user_roles):
    """
    Deletes an item by ID, validating the ID and checking user permissions.
    """
    try:
        item_id = int(item_id_str)
        if item_id <= 0:
            return {"error": "Invalid item ID.", "status": 400}
    except ValueError:
        return {"error": "Item ID must be an integer.", "status": 400}

    # Simulate authorization: Only users with 'admin' role can delete
    if "admin" not in user_roles:
        return {"error": "Forbidden: Requires 'admin' role.", "status": 403}

    # Simulate checking if item exists
    if item_id not in [10, 20, 30]: # Example existing items
        return {"error": "Item not found.", "status": 404}

    # Simulate database deletion (no actual DB call, just a placeholder)
    return {"message": f"Item {item_id} deleted successfully.", "status": 204}

def validate_password_strength(password_str: str) -> bool:
    """
    Validates if a password string meets basic strength requirements:
    minimum length, presence of uppercase, lowercase, and a digit.
    """
    if not isinstance(password_str, str):
        return False

    if len(password_str) < 8:
        return False

    has_lower = False
    has_upper = False
    has_digit = False

    for char in password_str:
        if 'a' <= char <= 'z':
            has_lower = True
        elif 'A' <= char <= 'Z':
            has_upper = True
        elif '0' <= char <= '9':
            has_digit = True

    return has_lower and has_upper and has_digit
